def transform(grid):
    # The object is made of 2x2 square tiles and 3-cell L tiles.
    # Color the square tiles 1; color Ls by their missing corner.
    cells = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8}
    n = len(cells)
    out = [[0 for _ in row] for row in grid]
    tiles = []
    # Candidate tiles: square (color 1) or L triomino (orientation colors 2-4).
    for r, c in cells:
        sq = {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if sq <= cells:
            tiles.append((sq, 1))
    # L candidates in each 2x2 window; known palette from demonstrations.
    palette = {1: 2, 2: 4, 3: 3}  # missing TL, BL, BR respectively
    for r, c in cells:
        box = {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        for missing, color in palette.items():
            shape = box - {sorted(box)[missing]}
            if shape <= cells:
                tiles.append((shape, color))
    # Exact-cover search; prefer maximal number of square pieces, then stable row-major choice.
    best = None
    def search(rem, chosen):
        nonlocal best
        if not rem:
            score = (sum(1 for _, col in chosen if col == 1), len(chosen))
            if best is None or score > best[0]:
                best = (score, chosen[:])
            return
        if best is not None and len(chosen) >= best[0][0] + 1:
            pass
        cell = min(rem)
        opts = [(shape, color) for shape, color in tiles if cell in shape and shape <= rem]
        for shape, color in sorted(opts, key=lambda x: (-len(x[0]), x[1], sorted(x[0]))):
            search(rem - shape, chosen + [(shape, color)])
    search(cells, [])
    if best is None:
        return [row[:] for row in grid]
    for shape, color in best[1]:
        for r, c in shape:
            out[r][c] = color
    return out
