def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 8}
    h, w = len(grid), len(grid[0])
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if box <= cells:
                tiles.append((box, 1))
            for missing, color in [((r,c),2), ((r,c+1),4), ((r+1,c),3)]:
                shape = box - {missing}
                if shape <= cells:
                    tiles.append((shape, color))
    solutions = []
    def search(rem, chosen):
        if not rem:
            solutions.append(chosen[:])
            return
        cell = min(rem)
        options = [(s,col) for s,col in tiles if cell in s and s <= rem]
        for shape, color in sorted(options, key=lambda x: (-len(x[0]), x[1], sorted(x[0]))):
            search(rem-shape, chosen+[(shape,color)])
    search(cells, [])
    if not solutions:
        return [row[:] for row in grid]
    # Choose the cover with the maximum number of 2x2 square tiles, matching demonstrated tiling.
    chosen = max(solutions, key=lambda sol: sum(col == 1 for _,col in sol))
    out = [[0 for _ in row] for row in grid]
    for shape, color in chosen:
        for r,c in shape:
            out[r][c] = color
    return out
